    ('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:286','A03_CODIGO_NINEZ_01','HN:CODIGO_NINEZ','82bbf79338b4df3c129d07e25938eecbea9874e56371afa95aacd38f799f90f0'),
    ('A03_CODIGO_NINEZ_01:CODIGO_NINEZ:287','A03_CODIGO_NINEZ_01','HN:CODIGO_NINEZ','fbfc90a43802b9f43c4ce601a8514f269af581a285a26dd25aef2bcdaf6d3736'),
