('PILOTO_D284_2013_01:DECRETO_284_2013:1','mayalex_normativos','10_LEYES_REGLAMENTOS','- A efecto de facilitar la formalización de las
actividades mercantiles por parte de quienes las desempeñan y
fomentar el desarrollo de la iniciativa empresarial, se autoriza la
Constitución de Sociedades Mercantiles bajo cualquier modalidad
de las reconocidas por el Código de Comercio, así como su
modificación, transformación, fusión, escisión, división, aumento
de capital u otros actos relacionados con su normal actividad y
desempeño cumpliendo solamente con las formalidades
contempladas en este decreto y el reglamento que se emita al
efecto.','1','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":1,"article_sha256":"dd3fafddf9a11de48b52ffde8e9c3a8fb9fe5cb339704bd5e0fb7241ad12a933","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','1','9b39a86315ef3e3e4875e6ff00ec5bd81f3e23b2a2397a2af8d1cff2cf3497a5','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:2','mayalex_normativos','10_LEYES_REGLAMENTOS','- A las sociedades mercantiles constituidas
bajo este régimen les son aplicables las disposiciones del Código
de Comercio relativas al tipo de sociedad de que se trate, así

como las de otras leyes de la República en lo que no se opongan
a lo dispuesto en este Decreto.

No pueden ser creadas bajo esta modalidad las sociedades que
tengan como finalidad el desarrollo de actividades objeto de
regulación y supervisión especial por parte del Estado, tales como
las que se dediquen a actividades relacionadas con el sistema
financiero.','2','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":2,"article_sha256":"6b1e63161002980df147b9a7862155376c8ce84ba6c92db1f8f4ce46287ab183","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','2','bcf5e2c99b7114b0a7df7950b76fc8daf049ea60583772ee6f3713aa13e1d65e','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:3','mayalex_normativos','10_LEYES_REGLAMENTOS','- La creación de sociedades mercantiles bajo
esta modalidad, se debe hacer a través de un formulario especial
único que debe ser creado para tal efecto por el Registro Mercantil
y que debe estar disponible en sus oficinas en formato físico o en
formato electrónico a través del internet. Los formularios pueden
llenarse y presentarse por quien o quienes deseen constituirse o
por apoderado debiendo en este último caso acreditarse el poder
con que actúe debidamente autenticado en su caso.

Las firmas deben ser autógrafas e impuestas ante Ministro de Fe
o ante el Registrador Mercantil cuando la constitución se haga en
formulario físico o electrónicas cuando se haga en formulario
electrónico. Los honorarios que cobren los Ministros de Fe deben
ser libremente determinados en conjunto con las partes.','3','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":3,"article_sha256":"a1c2b57206f7d23d766038e938a7e88770bf5389856c40dedd427194a347d392","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','3','192a0d9bd326f9d918bca351281957f5de7bb89af71534aa9f67e52de5e778b2','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:4','mayalex_normativos','10_LEYES_REGLAMENTOS','- El Registro de las sociedades constituidas
bajo esta modalidad debe hacerse en un registro electrónico único
de nivel nacional, pudiendo abrirse ventanillas en cualquier lugar
del territorio de la República. El registrador debe recibir el
formulario de inscripción y hacer el registro calificando únicamente
que la finalidad sea lícita, asignándole el número de matrícula
correspondiente, digitalizando y guardando el mismo en la base
de datos que al efecto se lleve. Dicha base de datos debe ser
gratuitamente accesible en línea por cualquier persona para efectos
de consulta.','4','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":4,"article_sha256":"0ea969999582489fed531e87764644902800297aa4e9fe2a93ecb1b79ab76a9d","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','4','a2d29f8b96a2242e6914e8ce52915c37af4bd78949a6c0a8a595fb9570d2a5f2','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:5','mayalex_normativos','10_LEYES_REGLAMENTOS','- Las sociedades mercantiles formadas al
amparo de esta Ley pueden ser creadas con un solo socio. El
establecimiento de capital mínimo al momento de su creación será
de carácter estrictamente voluntario debiendo insertarse en el
documento de su creación como una estipulación de carácter
especial en los casos en que así sea requerido por el o los socios.
Las sociedades creadas sin estipulación de capital mínimo por
más de un socio deben señalar los porcentajes de participación
de cada uno dentro de la misma. La tasa registral a pagar cuando
no se estipule el capital de la sociedad es la establecida para
actos de cuantía indeterminada.

Cuando la sociedad sea por acciones, las mismas pueden constar
en títulos que reúnan los requisitos establecidos en el Código de
Comercio o en anotaciones en cuenta de conformidad con lo
establecido en la Ley de Mercado de Valores.','5','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":5,"article_sha256":"fb2ab402e102bf96f28a74165a7f98eddf02ce4ee42bf09d5001e3b016bf1690","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','5','1f569907b1fc36983af6240fd3887602fed371be5f0b617c672e0d9f3bc0393d','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:6','mayalex_normativos','10_LEYES_REGLAMENTOS','- Las reuniones de asamblea de socios y las
de los órganos de administración de estas sociedades mercantiles
pueden llevarse a cabo en cualquier lugar dentro y fuera del
territorio nacional o por medios electrónicos, debiendo siempre
dejarse constancia fidedigna de la asistencia de quienes hayan
participado en las mismas.

La convocatoria para dichas reuniones puede hacerse mediante
publicación en un medio de comunicación masivo o mediante
correo electrónico con constancia de recibo. La misma debe
hacerse con la antelación que determinen los socios en el
documento constitutivo, que para las reuniones de asamblea de
socios salvo el caso de las asambleas totalitarias, no puede ser
menor de cuarenta y ocho horas o, cuando la reunión fuese a
llevarse a cabo fuera del territorio nacional, de diez (10) días
hábiles. Las reuniones de los órganos de administración pueden

convocarse en el mismo día si así se establece en el documento
constitutivo.

Cuando la Asamblea se lleve a cabo fuera del país se deben
habilitar los mecanismos para que los socios que lo soliciten puedan
participar por medios electrónicos en las discusiones y votaciones
que se lleven a cabo.','6','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":6,"article_sha256":"c7dd9274fb78f2eee667597636c73409f7961cc9f39b44339e9a8d77d6382889","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','6','ae7f668572adec878c9e2dca1ff2107a1a9d4e32f4dc3f8dae71c16c93035444','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:7','mayalex_normativos','10_LEYES_REGLAMENTOS','- Para efectos de lo estipulado en el Artículo
36 del Código de Comercio, las sociedades mercantiles creadas
al amparo de este decreto pueden llevar el control de los actos de
la asamblea de socios o de sus órganos de administración en
formato electrónico. No se requiere autorización alguna ni
notificación de ninguna autoridad del gobierno central,
departamental o municipal de los libros sociales y contables de la
sociedad. Tampoco se debe cobrar tasa o impuesto alguno
relacionado con dichos libros. Los controles de los actos de la
sociedad y su contabilidad pueden ser inspeccionados por
cualquiera de los socios a su simple requerimiento por escrito.
La contabilidad de estas sociedades puede llevarse mediante
sistemas informáticos que cumplan con las normas contables
requeridas por el Estado sin necesidad de autorización o
notificación a ninguna autoridad.','7','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":7,"article_sha256":"e80cf8f06cacf167b28ce878a328bb8b64e3c6b1c21068557b2780e6fc4f8406","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','7','4c0e2c24edab682746dc0f52586efcdb812ce150e69dddbfc344149aef8f63a2','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:8','mayalex_normativos','10_LEYES_REGLAMENTOS','- Cuando así lo estableciere el documento
constitutivo de la sociedad, puede dejarse constancia de las
reuniones de asamblea de socios y las de los órganos de
administración en vídeo. En estos casos no es necesario llevar
libros de actas, pero debe dejarse archivado el vídeo de la reunión
respectiva de forma adecuada que impida o minimice su deterioro
con el paso del tiempo. De éste vídeo se debe extender copia a
cualquiera de los socios a su simple requerimiento por escrito.

El secretario de la asamblea o, en el caso de los órganos de
administración de la sociedad, el secretario de éstos o quien haga
sus veces, debe elaborar y firmar un resumen de los acuerdos
tomados para ser entregado en físico o por medios electrónicos a
los socios y a los miembros de los órganos de gobierno y
posteriormente archivado para efectos de control y memoria
histórica de la sociedad.','8','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":8,"article_sha256":"6208cb38231a1469fe6ccc1a0da60e03711d7e224e921bf9597ffc9adb592ea9","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','8','8a86453ab19f6dda85a51425ded410ca70cb1fbe308618b620c5d7038fc9ac09','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:9','mayalex_normativos','10_LEYES_REGLAMENTOS','- Las tasas registrales y otros cargos deben
poder cancelarse al momento de la inscripción en la misma
ventanilla del Registro Mercantil o en ventanilla separada de una
institución bancaria, debiendo extenderse el recibo
correspondiente detallando los montos correspondientes a cada
cobro. Dicho recibo constituye prueba suficiente del pago por lo
que no se requiere la imposición de timbres u otra especie fiscal
para acreditarlos. Los montos recaudados deben ser distribuidos
entre las instituciones beneficiarias.','9','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":9,"article_sha256":"6e12f208dc6c487c408a4a40f4d6e864e7f098442ff0338646fd7fbab13580ee","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','9','aace3fa9d9e512f197532ef2ce16968548335382386c95b56cbbcdb447b4f8f1','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:10','mayalex_normativos','10_LEYES_REGLAMENTOS','- Los entes encargados del Registro
Mercantil deben crear los mecanismos para que en un plazo no
mayor de un (1) año a partir de la entrada en vigencia de esta
Ley, la constitución de sociedades mercantiles bajo la modalidad
establecida en la presente Ley, pueda llevarse a cabo
opcionalmente en línea mediante el uso de firmas electrónicas.','10','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":10,"article_sha256":"dea024e129ece17e175047a42c8860170908d49f38ddfe654881cee719b14ddb","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','10','20a3c339603854d0c44654448453fd75aa91906ce4840983b593b6dd04784d8f','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:11','mayalex_normativos','10_LEYES_REGLAMENTOS','- El formulario especial debe contener la
información necesaria para que en el mismo acto de registro se
autorice y haga entrega del Carnet de Registro Tributario Nacional,
también debe habilitarse a quienes lo soliciten para que a través
del mismo formulario se haga la notificación de inicio de
operaciones establecidas en el Artículo 10 de la Ley de Impuestos
Sobre Ventas y la inscripción de una Cámara de Comercio

requerida según el Artículo 384 del Código de Comercio para lo
cual la Dirección Ejecutiva de Ingresos (DEI) y las Cámaras de
Comercio deben hacer las coordinaciones necesarias con los entes
encargados del Registro Mercantil, para delegar en éstos, la
emisión de dichos documentos.

Asimismo debe incorporarse al formulario la opción para que
pueda emitirse a quienes lo soliciten y en el mismo acto del registro,
el permiso de operación municipal respectivo sujeto al pago de
las tasas que correspondan a favor de la municipalidad en la que
la sociedad vaya a operar. La municipalidad respectiva tendrá
reservado el derecho de inspeccionar posteriormente a la empresa
para comprobar la veracidad de lo declarado para este efecto.
Para este fin debe realizarse la coordinación respectiva con las
municipalidades, lo cual puede hacerse por etapas, empezando
por las municipalidades más grandes.','11','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":11,"article_sha256":"397547f2b242b90fd9699ceb371cb9157c12b1058044e4979bd321311b7fec4f","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','11','1f340113fe62601d02d1c9f09120158370adc515a257fe3c0d50357d9112e3ed','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:12','mayalex_normativos','10_LEYES_REGLAMENTOS','- El Registro Mercantil debe desarrollar por
vía reglamentaria los procedimientos para la modificación,
transformación, fusión, división, aumento de capital de las
sociedades mercantiles creadas bajo la modalidad establecida en
esta Ley mediante el uso de formularios en físico o electrónico,
debiendo seguirse en lo que sea aplicable los requerimientos del
Código de Comercio. Los formularios deben ser llenados y
presentados por los socios o mediante apoderado.','12','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":12,"article_sha256":"fbfb028e6cb4b6510c3013211d425bbda5fb17969989115cdcf501aa8ca7d6b5","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','12','add8cf193a2439b469c5af088696930f84c566a47b42045720a74aeb95bf87a7','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:13','mayalex_normativos','10_LEYES_REGLAMENTOS','- Reformar los artículos 14, 15, 18, 157,
169, 189, 193, 210, 222, 224, 226 y 228 del Código de Comercio
contenido en el Decreto Legislativo 73-50 y sus reformas, los
cuales deben leerse de la siguiente manera:

“ARTÍCULO 14.- El Contrato Societario debe contener:

I.

Lugar y fecha en que se celebre el acto;

II. Los nombres, nacionalidad y domicilio de las personas físicas, morales o jurídicas que constituyan la sociedad;
III. La clase de sociedad que se constituya;
IV. La finalidad de la sociedad;
V. Su razón social o su denominación;
VI. Su duración o la declaración expresa de constituirse por
tiempo indeterminado;
VII. La expresión del porcentaje de participación de cada socio
cuando no se haga estipulación de capital mínimo todo lo
que aporta en dinero o en otros bienes y el valor atribuido a
éstos;
VIII. El domicilio de la sociedad;
IX. La manera conforme a la cual haya de administrarse la
sociedad y las facultades de los administradores;
X. El nombramiento de los administradores y la designación de
los que han de llevar la firma social;
XI. La manera de hacer la distribución de las utilidades o pérdidas entre los socios;
XII. El importe de las reservas;
XIII.Los casos en que la sociedad haya de disolverse
anticipadamente;
XIV. Las bases para practicar la liquidación de la sociedad; y,
XV. El modo de proceder a la elección de los liquidadores
cuando no hayan sido designados anticipadamente.
Cuando la sociedad constituida tenga una finalidad objeto de
regulación por parte del Estado, debe además indicarse el capital
mínimo de conformidad con los requerimientos del órgano
regulador.”

“ARTÍCULO 15.- El contrato societario, así como sus
reformas o adiciones, deben inscribirse en el Registro Público de
Comercio.

Las sociedades inscritas legalmente en el Registro Mercantil tienen
personalidad jurídica y no pueden ser declaradas inexistentes o
nulas con efectos retroactivos. Declarada la inexistencia o la
nulidad del acto constitutivo, se procede a la disolución y
liquidación de la sociedad.

La ineficacia de la declaración de voluntad de algún socio se
considera como causa de separación a favor del mismo, el que
tiene además los derechos que le corresponden según la legislación
común.”

“ARTÍCULO 18.- Si el contrato societario o sus reformas
no se presentaren para su inscripción en el Registro Mercantil
dentro de los quince (15) días siguientes a su otorgamiento,
cualquier socio puede gestionarla judicial o administrativamente.

Cualquier interesado o el Ministerio Público puede requerir,
judicialmente a toda sociedad mercantil la comprobación de su
existencia regular. El requerimiento además de ser notificado
personalmente, debe ser publicado. Transcurridos cuatro (4) meses
del requerimiento sin que se haya comprobado la inscripción en
el Registro, la sociedad se pondrá en liquidación.

Cuando el contrato societario o su reforma fuere otorgado ante
Notario, este debe advertir a los otorgantes del deber que tienen
de registrarla, de los efectos del registro y de las sanciones
impuestas por el incumplimiento de esta obligación.”

“ARTÍCULO 157.- Todo accionista tiene derecho a solicitar
por escrito, en todo momento, a los directivos de la sociedad,
cualquier documento interno de la misma, salvo los documentos
que puedan constituir un secreto corporativo.

Se considera secreto corporativo todo documento que su
divulgación a personas no autorizadas pueda causar un daño
irreparable a la sociedad.

No puede ser considerado secreto corporativo los estatutos de
la sociedad, minutas del consejo de administración, minutas de la
asamblea de accionistas, estados financieros, informes anuales,
contratos de compraventa realizados por la sociedad, libros de
contabilidad o el registro de títulos o acciones.

Cualquier disposición de los estatutos de la sociedad contrario a
este Artículo es nulo de pleno derecho.

A falta de respuesta satisfactoria o rechazo por parte de los
directivos a la solicitud enunciada en este Artículo, todo accionista
puede solicitar ante el órgano jurisdiccional competente la
nominación de uno o varios expertos competentes.

Los expertos pueden acceder a todos los documentos de la
sociedad para de esta manera proveer con la información requerida
a los accionistas.

El experto también, a la solicitud de los accionistas, puede preparar
un informe sobre una o varias operaciones de gestión en caso de
que los accionistas tengan serias y justificadas dudas sobre el
correcto manejo de los negocios de la sociedad.

Las competencias del experto serán definidas por los tribunales
competentes. Los honorarios del experto estarán la cuenta de la
sociedad.

Los documentos o el informe solicitado deberán ser dirigidos a
los accionistas, al consejo de administración y al comisario. Estos
documentos o informes deben ser anexados al informe anual de
la sociedad.”

“ARTÍCULO 169.- Son asambleas extraordinarias, las que
se reúnen para tratar cualquiera de los siguientes asuntos:

I. Modificación del contrato societario;
II. Emisión de obligaciones o bonos;
III. Autorización de transacciones entre partes vinculadas
superiores al cinco por ciento (5%) de los activos de la
sociedad; y,
IV. Los demás para los que la ley o el contrato societario lo exijan.

Estas asambleas pueden reunirse en cualquier tiempo.”

“ARTÍCULO 189.- A solicitud de los accionistas que reúnan
el cinco por ciento (5%) de las acciones representadas en una
asamblea, se debe trasladar, para dentro de tres (3) días y sin
necesidad de nueva convocatoria, la votación de cualquier asunto
respecto del cual no se consideren suficientemente informados.
Este derecho puede ejercitarse sólo una vez para el mismo asunto.”

“ARTÍCULO 193.- Son nulos los acuerdos de las asambleas:

I. Cuando los socios no tuvieren capacidad para adoptarlos,
dada la finalidad social estatutaria;

II. Cuando se tomaren con infracción de lo dispuesto en los
artículos 177, 178 y 179 del Código de Comercio salvo que
al momento de la votación estuviere representada la totalidad
de las acciones y ningún accionista se opusiere a la adopción
del acuerdo;

III. Cuando no exista quórum en la asamblea o en la reunión de
los socios;

IV. Cuando tengan un objeto ilícito, imposible o fueren contrarios
a las buenas costumbres;

V. Cuando fueren incompatibles con la naturaleza de la sociedad
anónima, o por su contenido violasen disposiciones dictadas
exclusiva o principalmente para la protección de los acreedores
de la sociedad, o en atención al interés público; y,

VI. Cuando las transacciones enunciadas en el Artículo 210 del
Código de Comercio causen perjuicios a la sociedad y a sus
accionistas.”

“ARTÍCULO 210.- Salvo pacto en contrario, es presidente
del consejo el consejero primeramente nombrado y en defecto
de éste el que le siga en el orden de la designación.

Para que el consejo de administración funcione legalmente, debe
asistir, por los menos, la mitad del número estatutario de sus
miembros y salvo los casos en que el pacto social establezca una
mayoría más alta para asuntos específicos, sus resoluciones son
válidas cuando sean tomadas por la mayoría de los presentes. En
caso de empate, quien actúe como presidente del consejo decidirá
con voto de calidad.

Los estatutos determinan la forma de convocatoria del consejo,
lugar de reunión, los requisitos para el levantamiento de las actas
y los demás detalles sobre el funcionamiento del consejo.

Las irregularidades en el funcionamiento de éste, no son oponibles
a terceros de buena fe, sin perjuicio de la responsabilidad de los
consejeros frente a la sociedad. A las sesiones del consejo deben
ser citados los comisarios.

Son consideradas transacciones entre partes vinculadas toda
transacción:

I. Entre la sociedad y uno de sus administradores o consejeros;

II. Entre la sociedad y terceros en las cuales un administrador o
consejero esté interesado de cualquier modo, o en las cuales
trate con la sociedad mediante persona interpuesta; y,

III. La sociedad y otra empresa, si uno de los administradores o
consejero es propietario o administrador o consejero de la
última.

Las transacciones enunciadas en este Artículo deben ser sometidas
a autorización especial conforme a la regla siguiente:

Si la transacción o la suma de varias transacciones con la misma
contraparte durante el mismo período es inferior al cinco por ciento
(5%) de los activos de la sociedad, esta debe ser autorizada por
el consejo de administración. Cuando la transacción o la suma de
varias transacciones con la misma contraparte durante el mismo
período exceda al cinco por ciento (5%) de los activos de la
sociedad, esta debe ser autorizada por la asamblea extraordinaria
de accionistas.

Los administradores o consejeros interesados deben abstenerse
de votar en estas resoluciones y en caso de hacerlo su voto no
podrá ser contabilizado.

Las transacciones enunciadas en el Artículo 210 serán nulas si no
se respetan las condiciones enunciadas en el mismo o si estas
causan un perjuicio económico a la sociedad o a los accionistas.”

“ARTÍCULO 222.- El administrador o los consejeros durante
el ejercicio de sus funciones deben:

I. Ejercer sus funciones en el mejor interés de la sociedad;

II. Hacer prevalecer los intereses de la sociedad y de los

accionistas antes que los suyos;

III. Evitar los conflictos de interés actuales y potenciales;

IV. Asegurar que los convenios enunciados en el Artículo 210

sean autorizados por los órganos societarios competentes;

V. Abstenerse de hacer uso abusivo, directo o indirecto, de sus

funciones para tomar, o hacer que otros miembros de la
estructura societaria tomen, decisiones que son contrarias al
interés social de la sociedad; y,

VI. Desempeñar su gestión con la prudencia y diligencia con la

cual una persona con las mismas funciones, en una situación
comparable, hubiera actuado para proteger los intereses de
la sociedad y los accionistas.

El administrador o los consejeros son responsables individual y
solidariamente de los daños causados a la sociedad o a terceros
por causa de sus acciones u omisiones; violación a las disposiciones
legislativas o reglamentarias aplicables a las sociedades anónimas,
en particular los deberes enumerados en este Artículo; violación
de los estatutos de la sociedad o por las faltas cometidas durante
su gestión.

El administrador o los consejeros implicados en transacciones
enunciadas en el Artículo 210, que por sus acciones u omisiones;

o por violaciones de los deberes enumerados en este Artículo;
generen perjuicios a los accionistas, a la sociedad o a terceros,
no podrán ampararse de una decisión de la asamblea general
para deslindarse de responsabilidad.”

“ARTÍCULO 224.- Los consejeros son solidariamente
responsables por su administración, con las siguientes excepciones:

I. En los casos de delegación siempre que por parte de los
consejeros no hubiese dolo o culpa grave, al no impedir los
actos u omisiones perjudiciales; y,
II. Cuando se trate de actos de consejeros delegados, cuyas
funciones se hubiesen determinado en los estatutos.”

“ARTÍCULO 226.- La responsabilidad de los
administradores frente a la sociedad queda extinguida:

I. Por la aprobación del balance respecto de las operaciones
explícitamente contenidas en él o en sus anexos. Se exceptúan
los siguientes casos:
a) Aprobación del balance en virtud de datos no verídicos; y,
b) Si hay acuerdo expreso de reservar o ejercer la acción de
responsabilidad;
II. Cuando el administrador o los consejeros hubieren procedido
en cumplimiento de acuerdo de la asamblea general que no
sean notoriamente ilegales; Esta excepción no se aplicará en
el caso de la autorización por la asamblea general
extraordinaria de transacciones entre partes vinculadas
enunciadas en el Artículo 210 del Código de Comercio; y,
III. Por aprobación de la gestión o por renuncia expresa o
transacción acordada por la asamblea general.”

“ARTÍCULO 228.- Aun en los casos del Artículo 226, los
accionistas que representen el cinco por ciento (5%) del capital
social por lo menos, pueden ejercitar directamente la acción de
responsabilidad civil contra el administrador o los consejeros,
siempre que se satisfagan los requisitos siguientes:

I. Que la demanda comprenda el monto total de las
responsabilidades en favor de la sociedad y no únicamente el
interés personal de los provenientes; y,
II. Que en su caso, los actores no hayan aprobado la resolución
tomada por la asamblea general de accionistas sobre no haber
lugar a proceder contra el administrador o consejeros
demandados.
Los bienes que se obtengan como resultado de la reclamación,
con deducción de los gastos erogados en ésta, serán percibidos
por la sociedad.”','13','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":13,"article_sha256":"1e45744f3ca841e7fbf9a1aa465d35903ac9f0cca98c44e1b0baf7c721063a5c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','13','95c76dc126d07a5fa318be127993cc50709fec120d4242da352205e043e51d8d','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:14','mayalex_normativos','10_LEYES_REGLAMENTOS','- Reformar los Artículos 1782 y 1789 del
Código Civil, los cuales deben leer de la siguiente manera:

“ARTÍCULO 1782.- La sociedad o compañía es un
contrato por el cual se aporta un capital o un bien o bienes tangibles
o intangibles como patrimonio con el objeto de limitar la
responsabilidad al mismo y de que las ganancias o pérdidas que
resulten de la especulación sean distribuidas al o los socios en las
proporciones acordadas en el documento de constitución.

La sociedad podrá ser unipersonal cuando se constituya por una
sola persona natural o jurídica, o colectiva cuando se constituya
por dos o más.”

“Artículo 1789.- El contrato de sociedad puede hacerse
constar en escritura pública o en documento privado que reúna

las formalidades establecidas en la Ley y debe ser inscrito en el
Registro Mercantil.”

TÍTULO II

DE LA SIMPLIFICACIÓN DE LA EJECUCIÓN DE
HIPOTECAS PARA LA FACILITACIÓN DEL ACCESO
AL CREDITO Y LA REACTIVACIÓN DEL SECTOR
DE VIVIENDA','14','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":14,"article_sha256":"9363bdb444adca486bca89f25ce8bb13787b5241a9dc18d6ead2b93414c1b062","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','14','c019e6211b89adab7e873fae0b63e4dee97f67aca2c4b6f90a3cecc6fbc9134b','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:15','mayalex_normativos','10_LEYES_REGLAMENTOS','- Es lícito el pacto en el que las partes
acuerden renunciar al procedimiento judicial para la ejecución de
garantías y sujetarse a un procedimiento especial de ejecución
ante notario. El pacto suscrito para tal efecto puede constar en el
mismo instrumento público que contenga la garantía o en
instrumento público separado y debe ser inscrito en el registro de
la propiedad que corresponda. Dicho pacto debe establecer el
precio base del inmueble dado en garantía y la forma del
requerimiento, y sujetarse a los procedimientos establecidos en
este decreto.','15','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":15,"article_sha256":"630bf51fa54f4136b5dd18957b84a6996dc758698f159577eea1ebf694a4e666","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','15','fe32758358227008a23c918fc8914b9d1462f0cbb306ae8fa840da45d547b2d4','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:16','mayalex_normativos','10_LEYES_REGLAMENTOS','- El Notario encargado de la ejecución
deberá verificar que la obligación conste en instrumento público
válido y que sea actualmente exigible. Hecho ésto, debe requerir
al deudor para que cumpla con la obligación contraída en el término
de veinticuatro (24) horas. En el mismo acto del requerimiento
debe notificársele:

1) La obligación pendiente y el monto de la misma;

2) El nombre del titular, el lugar donde pueda pagarse o el nombre
del establecimiento bancario y número de cuenta bancaria en
la que puede consignar el valor;

3) El día, lugar y hora en la que se llevará a cabo la venta en
pública subasta del bien dado en garantía conforme al precio
base establecido en el contrato; y ,

4) La expresión de ante quien debe efectuarse el pago o
consignación, que puede hacerse antes del plazo señalado
para el evento.

Ante este requerimiento no podrá hacerse más oposición que el
pago.','16','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":16,"article_sha256":"2a8780561b1b0fbb76fb01d84199f68d5cebaf35c71155e3b87f2eaaec3f2b1e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','16','0547b74a6851824b43a600c77b17732798bcdf985506cce266cd9179cf420347','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:17','mayalex_normativos','10_LEYES_REGLAMENTOS','- El requerimiento puede hacerse en una
dirección física o electrónica previamente pactada, o en su defecto
en el domicilio o el lugar de empleo del deudor. Si el mismo no se
encontrare presente bastará con fijar una copia en la entrada del
lugar debiendo también entregársele copia a cualquier persona
que allí se encuentre y a dos (2) de los vecinos del lugar quienes
actuarán como testigos del acto. Además, puede realizarse una
filmación en vídeo de estas actuaciones la cual tendrá fuerza legal.
Si se desconociere el paradero del deudor, el requerimiento debe
publicarse durante tres (3) veces consecutivas con un (1) día de
separación, en un diario de los de mayor circulación y un medio
de comunicación masiva con cobertura en el lugar del último
domicilio conocido de éste, después de lo cual se puede proceder
con la ejecución.','17','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":17,"article_sha256":"ee6007e774962184b8f0d780231a1efa69d49596b27c3e8d91fc3db81268ca39","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','17','d96720100dd0994f160d5abeaff0c2b56dcfe90a1dd68f0568c6e8ed22b9e553','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:18','mayalex_normativos','10_LEYES_REGLAMENTOS','- Cuando el pago se hiciere efectivo ante el
Notario en el plazo señalado, éste debe acreditar el mismo y dar
por cerrado el expediente, extendiendo el correspondiente recibo,
si se acreditase que el pago había sido hecho con anterioridad al
requerimiento el notario debe suspender el proceso y remitir las
diligencias ante el Juez de Letras correspondientes a fin de que el
mismo pueda determinar la veracidad o no del pago, para lo cual
debe dentro de las veinticuatro (24) horas siguientes a la recepción

de las diligencias abrirse de oficio la causa a prueba por un plazo
no mayor de cinco (5) días hábiles comunes después de las cuales
debe ordenar el cierre de dicho período de oficio. Si se
determinare que el pago es suficiente para dar cumplida la
obligación, el juez debe emitir resolución ordenando la suspensión
definitiva del proceso y el cierre de las diligencias.

Si resultare que el pago no ha sido efectivo o que el mismo es
insuficiente. Para dar por cumplida la obligación el juez de Letras
debe emitir la resolución respectiva dentro del mismo plazo
establecido en el párrafo anterior, mandando que las diligencias
sean enviadas nuevamente al notario para que este concluya el
proceso de ejecución si hubiere habido un pago parcial de
ejecución debe llevarse a cabo por el remanente.

La resolución del juez debe ser emitido en un plazo no mayor de
cuarenta y ocho (48) horas después de cerrado el período
probatorio establecido en el párrafo primero de este Artículo.','18','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":18,"article_sha256":"46f27018ffb922fdfe67267ed4dc6f93726d7cc1346f4a76bd972c1f84472050","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','18','a2b1d3a1a67b941ecc2e34c71a6217fe8862d5ed74f4eec47373e4543d0320a7','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:19','mayalex_normativos','10_LEYES_REGLAMENTOS','- El acta donde conste el requerimiento o
notificación por Notario debe inscribirse en el mismo asiento en
el que se haya inscrito la garantía. El registro de la notificación o
requerimiento como anotación en el asiento donde se encuentre
inscrito el bien o el acto o contrato tiene el mismo valor de los
embargos decretados judicialmente.','19','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":19,"article_sha256":"f861eac3835006032ffcec87b6924070274c26f5507e35a0f6c6439b5992a6c0","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','19','dd0aad2bdf5d2420e422aa288ee807d184db7b00cd021aa4cd4318ded6ea3adb','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:20','mayalex_normativos','10_LEYES_REGLAMENTOS','- La venta debe hacerse en pública subasta
a favor de quien ofrezca el mejor precio.

El acreedor puede participar en la subasta ofertando el valor de
su crédito o un monto superior.

En caso de que nadie participe en la subasta se debe adjudicar el
bien a favor del acreedor sin necesidad de que éste oferte su

crédito. En los casos en que el valor del bien rematado no cubra
el pago total de la obligación queda a salvo el derecho del acreedor
de perseguir otros bienes del deudor, debiendo constar en el acta
correspondiente.

De todo lo actuado debe levantarse el acta correspondiente. Esta
acta servirá de título traslaticio del dominio sobre la garantía,
debiendo inscribirse la misma.','20','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":20,"article_sha256":"96e0f9b8bc54d952d1fa8b5115ad41929e306e8025f8672e9f81a3cb07335d51","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','20','bd25656eb0147feecf49c0fe512f4b3c79b139de19dd3564d2eea613b8ca92b6','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:21','mayalex_normativos','10_LEYES_REGLAMENTOS','- Las normas para determinar la prioridad y
prelación de derechos de los acreedores sobre las garantías son
determinadas por la legislación de derecho privado que
corresponda.','21','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":21,"article_sha256":"7ab991804e2d1357dec7e497303d48a05d41f9445e237eeb8573274e62d4861c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','21','91cfdf6d3cc4372deea95dd27c95ff6a8334e58020b5ffdbf664c0e16ebcc095','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:22','mayalex_normativos','10_LEYES_REGLAMENTOS','- Cuando hayan otros acreedores
garantizados por los bienes que se ejecutarán, el acreedor
interesado en su ejecución debe notificarles a los otros acreedores
a través de notario. Cuando estos otros acreedores hayan
autorizado el empleo de una dirección física para practicar
requerimientos y notificaciones, se les puede notificar en esa
dirección.

Si no se encontraren en la misma, debe fijarse una copia de la
notificación en la entrada del lugar, debiendo también entregársele
copia a cualquier persona que ahí se encuentre y a dos (2) de los
vecinos del lugar quienes deben servir de testigos de este acto.

Esta notificación debe inscribirse en el asiento en que se
encuentre inscrito el bien dado en garantía.','22','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":22,"article_sha256":"3e3980cac2e711cb1f98c59c91dee73103560a8706f1a64534cd24846ca27c7c","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','22','4ee43158da3ddd489faef442b4b92da8eec1e64451a6f24762e416a4fa1bce39','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:23','mayalex_normativos','10_LEYES_REGLAMENTOS','- Cuando hayan varios acreedores éstos
pueden ponerse de acuerdo ante un notario sobre la forma en
que distribuirán los resultados de la venta por acreedor o de la
venta extrajudicial por Notario.','23','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":23,"article_sha256":"8e1d96e751a140e4ded40bbcbd51ca031ed219733037b67aa6ca8309982412bb","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','23','21ab8ec07e4ebac6bd70891841b82c57421b07d62fe8c184ff635ff7a5e696b4','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:24','mayalex_normativos','10_LEYES_REGLAMENTOS','- Cuando no se pueda notificar a los otros
acreedores que tengan derechos sobre la misma garantía o éstos
no lleguen a un acuerdo después de ser notificados, debe solicitarse
autorización especial del juez del domicilio donde se encuentren
los bienes para seguir adelante con el proceso de ejecución.

Para el otorgamiento de esta autorización el juez puede solicitar
que se rinda caución para garantizar los derechos de los otros
acreedores. Esta notificación debe inscribirse en el registro público.

Contra esta resolución no cabe recurso alguno.','24','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":24,"article_sha256":"d836d73cb71da180c44dd6faa2c1f891f5bc56782c17731c6d0f2923041ec0f7","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','24','0478827b260cbc37307a72d162d5ce7f6dfc324214ab48be46e41d1166acac6f','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:25','mayalex_normativos','10_LEYES_REGLAMENTOS','- El Notario ante quien se hubiese constituido
una garantía no puede participar en la ejecución de la misma.

TÍTULO III

DE LA REESTRUCTURACIÓN DE LA
INSTITUCIONALIDAD PARA LA PROMOCIÓN DE
INVERSIONES Y LA MAYOR EFICIENCIA DE LAS
MISMAS','25','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":25,"article_sha256":"66091d05d8de2b9b42a30ea5420cdaa21699bd14eeffac25bae2d43ef11471a2","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','25','3e2d8c99095969b2c2d26a36d09b586c67fa9fbd0cbc656e5a7d4dd6cf85953a','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:26','mayalex_normativos','10_LEYES_REGLAMENTOS','- Reformar los Artículos 21, 40, 42, 43,
44, 45, 46 y 50 de la Ley para la Promoción y Protección de
Inversiones contenida en el Decreto Legislativo No. 51-2011 y
en sus decretos de reforma e incorporar por adición al mismo el
Artículo 17-A; todos los cuales se leerán así:

“ARTÍCULO 17-A.- Aún cuando lo hubiese decretado el
Consejo de Secretarios de Estado, los inmuebles sobre los cuales
se desarrollen proyectos que se sujeten a estas disposiciones, no
les serán aplicables las disposiciones para la regularización de
inmuebles por necesidad pública contenidos Ley de Propiedad.”

“ARTÍCULO 21.- La duración máxima de los contratos de
estabilidad será de quince (15) años, excepto en el caso de
inversiones bajo la modalidad de Alianza Público-Privada, cuya
duración será la que se establezca en las cláusulas del contrato
respectivo o en el acuerdo separado que se suscriba al efecto.

Cuando se trate de proyectos relacionados a actividades forestales
o mineras, el término de la vigencia podrá ampliarse hasta
veinticinco (25) años.”

“ARTÍCULO 40.- Las inversiones calificadas como
proyectos de interés nacional están sujetas a la aplicación de un
procedimiento acelerado de inversión. Previo a la declaratoria
del Consejo Nacional de Inversiones o COALIANZA según
corresponda, debe realizar un análisis económico y de viabilidad
del proyecto para lo cual debe emitir un dictamen con la respectiva
recomendación.

Dicha recomendación debe ser trasladada al Poder Ejecutivo para
que el Presidente de la República en Consejo de Secretarios de
Estado o en un gabinete sectorial especial, si lo estima
conveniente, emita un Decreto Ejecutivo conteniendo la
declaración de interés nacional y un certificado de incorporación
y viabilidad de operación. Esa certificación hace las veces de
todos los permisos o licencias requeridos por la legislación
hondureña para desarrollar el proyecto.

Este procedimiento desde su inicio hasta su conclusión con la
emisión del Decreto Ejecutivo debe realizarse en un término no
mayor de treinta (30) días hábiles”.

“ARTÍCULO 42.- Créase el Consejo Nacional de
Inversiones (CNI) como una entidad de derecho público, con
personalidad jurídica y patrimonio propio, cuyos fines principales
son:

a) La promoción y desarrollo de la inversión privada;

b) La facilitación de trámites y asistencia a los inversionistas
antes, durante y después de establecida una inversión; y,

c) La formulación de propuestas de política pública encaminadas
a la creación de un clima favorable a la inversión tanto nacional
como extranjera.

El patrimonio del Consejo estará conformado por las donaciones
y aportaciones que reciba de quienes se beneficien de los servicios
que preste, las aportaciones que reciba por parte del Estado de
Honduras, los recursos provenientes de donaciones y otros de
origen lícito que se produzcan como resultado de sus operaciones.
Asimismo, se le autoriza para contratar empréstitos y realizar
inversiones encaminadas a incrementar su patrimonio en
instrumentos de bajo riesgo en los mercados nacional o
internacional. Las aportaciones y donaciones que reciba el Consejo
deberán publicarse en su sitio web, detallando los montos o valores
de la aportación o donación y el nombre o razón social del o los
aportantes, así como los fines a los que el mismo sea destinado.

El Estado podrá realizar aportes periódicos o aislados de recursos
para fines específicos al mismo, o subcontratarlo para actividades,
consultorías, misiones o proyectos específicos relacionados con
sus funciones.”

“ARTÍCULO 43.- La Junta Directiva del Consejo Nacional de
Inversiones estará integrada de la siguiente manera:

Por el Sector Público un Comisionado de COALIANZA y tres
Secretarios de Estado nombrados por el Presidente de la
República; y por el Sector Privado participarán cuatro

representantes que serán nombrados por el Presidente de la
República de un listado de diez (10) personas que le será remitida
por el COHEP. Su rotación y condiciones de nombramiento por
más de una vez, se determinará en el reglamento de esta
Ley.”

“ARTÍCULO 44.- Son funciones del Consejo Nacional de
Inversiones:

a) Realizar la función de Secretaría del Consejo Nacional de
Competitividad e Innovación y presentar al Presidente de la
República las propuestas de política pública necesarias para
simplificar los trámites necesarios para llevar a cabo
inversiones de carácter privado o para iniciar un negocio, así
como para la obtención de los permisos y licencias necesarios
para su operación para lo cual deberá dar seguimiento a las
recomendaciones que al efecto se hagan en el Informe Doing
Bussiness del Banco Mundial u otros organismos
internacionales que lleven a cabo estudios similares;

b) Definir y/o actualizar anualmente en coordinación con la
Presidencia de la República y las entidades estatales sectoriales
la lista de los sectores prioritarios de inversión en Honduras y
diseñar estrategias para la promoción de los mismos;

c) Coordinar junto con la Secretaría de Estado en el Despacho
de Relaciones Exteriores las actuaciones en el extranjero de
su Secretario Ejecutivo. Para ello los miembros de su Junta
Directiva gozarán de estatus de embajadores y contarán con
plenos poderes de representación del Estado de Honduras;

d) Desarrollar, coordinar, impulsar y promover a través de su
Secretaría Ejecutiva el programa permanente de imagen de

país como principal componente de los esfuerzos para
mantenimiento de la identidad competitiva de Honduras en el
exterior. Las instituciones sectoriales del Estado deberán
coordinar con el Consejo Nacional de Inversiones cualquier
esfuerzo de promoción internacional que pretenda realizar bajo
sus ámbitos de competencia;

e) Promocionar internacionalmente a Honduras como un destino
de inversiones pudiendo delegar o subcontratar esta función
en otras entidades nacionales o extranjeras;

f) Trabajar en coordinación con la Secretaría de Estado en el
Despacho de Relaciones Exteriores y en estrecha relación y
armonía con las representaciones diplomáticas de Honduras
alrededor del mundo, a fin de proveerles con información
actualizada relativa a cambios en la legislación o la política del
Estado que pudieren incentivar o afectar la inversión, así como
de potenciales rubros atractivos para la misma;

g) Proveer a las cámaras de comercio u otras entidades según lo
estime conveniente información relativa a los cambios en la
legislación que afecten la inversión y la apertura de negocios
y procurar el establecimiento de una ventanilla única para
lograr este objetivo;

h) Recomendar la aprobación de los contratos de estabilidad
jurídica y remitirlos a la Presidencia de la República para su
suscripción y aprobación de conformidad con lo establecido
en el Artículo 25 de la presente Ley. Se exceptúan aquellos
casos en que el contrato este integrado como cláusula en un
contrato de una Alianza Público Privada;

i) Ser el ente encargado de gestionar y mantener la membresía
del Estado de Honduras en la Comisión de las Naciones
Unidas para el Derecho Mercantil Internacional (CNUDMI),
UNIDROIT, y otros organismos internacionales relacionados
dedicados al estudio del derecho mercantil, derecho
internacional de inversiones y otras disciplinas vinculadas;

j) Colaborar con el Poder Ejecutivo proponiéndole la regulación
de los organismos de derecho privado auxiliares de la
Administración Pública, cuando los mismos no se encuentren
regulados por ley; y,

k) Las demás que le fueren asignadas por esta ley o por su
reglamento.

El Consejo Nacional de Inversiones estará facultado cuando lo
estime necesario y dentro de los límites de su presupuesto para
contratar total o parcialmente los servicios que requiera para
evaluar y optimizar la calidad en el desempeño de sus funciones,
así como estudios relacionados con el clima de negocios en
Honduras.”

“ARTÍCULO 45.- Para la realización de sus actividades,
prestación de sus servicios y su sana administración, el Consejo
Nacional de Inversiones contará con el apoyo de una Secretaría
Ejecutiva cuyo titular será nombrado por el Presidente de la
República. Su nombramiento tendrá carácter de permanente
pudiendo ser removido por el Presidente de la República
únicamente por causa justificada.

La Secretaría Ejecutiva del Consejo Nacional de Inversiones
contará con el personal necesario para poder desempeñar sus

funciones. Las funciones de la Secretaría Ejecutiva serán las que
se establezcan en el reglamento de la presente Ley.”

“ARTÍCULO 46.- A fin de procurar la permanencia y
ampliación de las inversiones ya existentes, el Consejo Nacional
de Inversiones deberá también prestar los servicios que requieran
los inversionistas para la facilitación del desarrollo y ampliación
de las mismas, para lo cual deberá mantener una base de datos
de inversiones y mantenerse en contacto permanente con los
directores de empresas y entes gubernamentales involucrados, a
fin de detectar potenciales problemas que surgieren después del
establecimiento de la inversión y facilitar su solución de la manera
más eficiente posible.

En tal sentido se autoriza a la Secretaría Ejecutiva a crear una
unidad especializada o contratar los servicios de una entidad ya
existente para la prestación de servicios de post-inversión,
pudiendo establecer cobros por estos servicios.”

“ARTÍCULO 50.- Se autoriza al Consejo Nacional de
Inversiones a realizar un cobro equivalente al 0.25% de la
facturación anual por ventas o servicios realizados a aquellos
inversionistas que suscriban contratos de estabilidad con el Estado
en concepto de tasa por gestión y mantenimiento de los mismos
durante la vigencia del contrato.”','26','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":26,"article_sha256":"c88535cdb0bd582e4e3f7f0b3543f5d04388ea4f1e7740d5a904f3495c558b66","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','26','5dd5c0d5bcdcf53fa9339307094970b74d06a3ae8c92a52654e3a7091b864151','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:27','mayalex_normativos','10_LEYES_REGLAMENTOS','- Reformar los Artículos 29 y 34 de la Ley
de Promoción de la Alianza Público-Privada contenida en el
Decreto Legislativo No. 143-2010 y sus reformas, los cuales se
leerán así:

“ARTÍCULO 29.- Se autoriza a la Comisión para la
Promoción de la Alianza Público-Privada (COALIANZA) a
realizar un cobro de hasta el dos por ciento (2%) del valor de

cada proyecto autorizado al adjudicatario del mismo, en concepto
de tasa por los servicios que presta.

También se autoriza a la Superintendencia de Alianza Público-Privada, para percibir de las empresas privadas que suscriban
contratos de participación público-privada, un aporte por
regulación, a ser fijado mediante el correspondiente contrato de
hasta el uno por ciento (1%) del valor de la facturación anual,
hechas las deducciones correspondientes al pago de Impuesto
Sobre Ventas.

Los fondos obtenidos por dichos cobros, pasarán a ser
administrados mediante un Fideicomiso creado para cada
institución de los cuales la Comisión para la Promoción de la
Alianza Público-Privada (COALIANZA) y la Superintendencia
de Alianzas Público-Privada, serán los únicos beneficiarios
respectivamente. El producto de dichos fideicomisos servirá para
que cada institución cubra la totalidad o una parte de su
presupuesto. Las disposiciones para la conformación de estos
fideicomisos serán desarrolladas en el Reglamento de la presente
Ley.

Si de los recursos del fideicomiso de COALIANZA hubiere
fondos remanentes al final del Ejercicio Fiscal, los mismos se
reservarán para ser utilizados en la investigación y desarrollo de
nuevos proyectos, el rescate de proyectos en los que no se
hubiesen logrado resultados programados y el pago de gastos de
defensa del Estado.”

“ARTÍCULO 34.- Para ejercer los derechos y obligaciones
que se originan de las relaciones jurídicas reguladas por la presente
Ley, se requiere únicamente de la autorización para prestar un
servicio o desarrollar una infraestructura otorgado por la Comisión

para la Promoción de la Alianza Público-Privada
(COALIANZA).

La Comisión para la Promoción de la Alianza Público-Privada
(COALIANZA) deberá asistir al adjudicatario de un proyecto
en la tramitación y obtención de todos los permisos, licencias,
autorizaciones y demás actos administrativos requeridos por la
Administración Pública Central y/o Municipal, para operar la
Alianza Público - Privada (APP).”','27','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":27,"article_sha256":"cb5c2e8e99540e26c2a4d022dbcd83411a1ff3f0e8174384a0f481047ff26197","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','27','967fce842ffebd36aac9635d4868e73d7146e4260518f2fe7bc928d3bab40bfb','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:28','mayalex_normativos','10_LEYES_REGLAMENTOS','- Interpretar el Artículo 31 de la Ley de
Promoción de la Alianza Público Privada contenida en el Decreto
Legislativo No. 143-2010 y sus reformas, en el sentido de que el
párrafo último del mismo es una autorización para la determinación
de su propia política salarial incluyendo gastos de representación,
bonificaciones, dietas, viáticos y demás estipendios de
conformidad con los Artículos 361 y 362 del Código del Trabajo
contenido en el Decreto Legislativo No. 189 de 1959 y sus
reformas.','28','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":28,"article_sha256":"055defc57a403c445bcbd4db14abafa53ca5b70a473f715328107201551c624e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','28','2a91f50d450aba00e77a6fd9a9ea90f48cd2e711d80d4417d420339bac3801ee','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:29','mayalex_normativos','10_LEYES_REGLAMENTOS','- Interpretar el Artículo 35 de la Ley de
Promoción de la Alianza Público-Privada contenida en el Decreto
Legislativo No. 143-2010 y sus reformas, en el sentido que la
misma excluye de la aplicación de la Ley de la Jurisdicción de lo
Contencioso-Administrativo a los contratos que se otorguen y
procedimientos que se empleen.','29','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":29,"article_sha256":"6a43d858fca2861648337afe4ad8b16c7360d671fe22a334662f216215eefd48","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','29','1a2c662a5d21fb326318508478c15130112e07481089c2e69897218fda427980','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:30','mayalex_normativos','10_LEYES_REGLAMENTOS','- En lo procedente, será aplicable al Consejo
Nacional de Inversiones y a otras unidades de la administración
pública que el Presidente de la República autorice lo dispuesto en
los Artículos 29, 31 y 35 de la Ley de Promoción de la Alianza
Público - Privada contenida en el Decreto Legislativo No. 143-2010 y sus reformas.','30','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":30,"article_sha256":"d0aaf24a2120ee1032f32801363bdc2672b9768d8f6a885f03bdd0a86a4634a7","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','30','920e17543962d394df3cbee7dda8c83032c1ab240f9785294a9f95eaa22a7c91','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:31','mayalex_normativos','10_LEYES_REGLAMENTOS','- Son aplicables a la Ley de Promoción de
la Alianza Público Privada contenida en el Decreto Legislativo
No. 143-2010 y sus reformas los Artículos 3-A, 3-B, 6 y 111 de
la Ley de Contratación del Estado contenida en el Decreto
Legislativo Número 74-2001 de fecha 29 de junio del 2001 y en
sus decretos de reforma.

TÍTULO IV
DISPOSICIONES COMPLEMENTARIAS Y
TRANSITORIAS','31','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":31,"article_sha256":"4ad0dc3bd2d4832f66aa98823c2a18295877ccb6c464ad49ff7f28e7485c729e","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','31','956beb9944f4914853d25793ffbf8c8ed132ac50898803132fb1b3f8beced057','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:32','mayalex_normativos','10_LEYES_REGLAMENTOS','- Las referencias que en la Ley para la
Promoción y Protección de Inversiones se hagan a la Secretaría
Técnica del Consejo Nacional de Inversiones deberán entenderse
como menciones a la Secretaría Ejecutiva del Consejo Nacional
de Inversiones.','32','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":32,"article_sha256":"0a91788fcacaa0f7db7979168ccf8291bae7025d83c4ae7f744c0a082e085560","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','32','f9fa272a447ead9c7ef7dd0715ac16f86306f5567233a65bcd4cfbcca1bc07c5','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:33','mayalex_normativos','10_LEYES_REGLAMENTOS','- A efectos de dar cumplimiento a lo
establecido en los artículos 15, 16 y 29 del Decreto 51-2011
contentivo de la Ley para la Promoción y Protección de
Inversiones, los jueces de letras deberán instruir a quienes
presenten ante los tribunales acciones sobre los asuntos descritos
en el mismo sobre la existencia de esas disposiciones y el derecho
que les asiste para concurrir ante la instancia arbitral como vía de
solución primigenia a la disputa. A partir de la entrada en vigencia
del presente decreto, serán sujetos de nulidad aquellos procesos
que se hubieren seguido sin cumplir con este requisito.

La presente disposición deberá comunicarse al Consejo de la
Judicatura y la Corte Suprema de Justicia a fin de que se libren las
comunicaciones y se dicten las instrucciones que correspondan a
todas las instancias del Poder Judicial.','33','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":33,"article_sha256":"3826e43bbbcb2d2d24bec07d68f4958e47238bbd75879088f4684f7cb7ef64b1","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','33','e1bb23cd986325ecae3f6b27c4573b569440a3780a3b76b0727de718268ec940','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:34','mayalex_normativos','10_LEYES_REGLAMENTOS','- En un plazo no mayor de ciento ochenta
(180) días a partir de la entrada en vigencia de la presente Ley, la
Empresa Nacional de Artes Gráficas debe realizar todas las
gestiones necesarias para transformar el Diario Oficial La Gaceta
en una publicación digital para lo cual debe crearse el sitio web
respectivo. El Consejo Nacional de Inversiones puede colaborar
en la contratación de los servicios necesarios para dicha
transformación. Las publicaciones que a la fecha se hacen en el
Diario Oficial La Gaceta pasan a hacerse en la versión digital del
mismo, debiendo cobrarse únicamente el costo de hacer dicha
publicación en su sitio web. La Empresa Nacional de Artes
Graficas puede cobrar a quienes deseen una copia impresa en
papel simple del mismo.','34','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":34,"article_sha256":"fea7d81daa5f3213361280e0be42a2b0f88192fc788bde074603db5baf8396d3","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','34','9c0a7dbf1d495018fd59929f8ff7f76722a7ce5cbcc83d71ded064bda131da74','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:35','mayalex_normativos','10_LEYES_REGLAMENTOS','- La certificación autenticada por Notario,
emitida por una Institución del Sistema Financiero acreedora, en
la que acredite el pago total de una deuda garantizada, por hipoteca
es suficiente para realizar cancelación del gravamen en el Registro
de la Propiedad. La Institución del Sistema Financiero está en la
obligación de emitir, sin costo alguno a sus clientes, dichas
certificaciones. Los registradores de la propiedad no pueden exigir
ninguna otra formalidad para proceder a la cancelación de las
hipotecas.','35','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":35,"article_sha256":"7c795fceddd49049e8a50c085d8dee9c977c1787c0d79426fcab1b8f19c329e4","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','35','eed694a049c4294604aff2a13ae29a26f55e71596380c7b05bc0fdca456f0ae8','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:36','mayalex_normativos','10_LEYES_REGLAMENTOS','- Las normas contenidas en la presente Ley
deben reglamentarse por la Presidencia de la República a través
de la Secretaría de Estado en el Despacho de Finanzas (SEFIN)
dentro de los tres (3) meses siguientes a la entrada en vigencia de
la misma.','36','Decreto 284-2013, Ley para la Generación de Empleo, Fomento a la Iniciativa Empresarial, Formalización de Negocios y Protección a los Derechos de los Inversionistas (La Gaceta 33,445)','{"bytes_sha256":"a7eb221fdeff8977ae9cf907f926797b8d45cd7d90dc93ece7e32ee3581edee4","text_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","paquete":"PKG_DECRETO_284_2013_REFORMA_AL_CODIGO_DE_COMERCIO@v1","estado_fuente":"CLO_PENDING","procedencia":"Fuente validada por el receptor contra el registro de fuentes oficiales (CLO_PENDING); sin V4/V5 ni vigencia declarada","decreto":"284-2013","texto_origen":"TRANSCRIPCION_COTEJADA","transcripcion_sha256":"ba75b190d7e04e0e85851ee204d6d2deafba80f5e1a03e5e592f7968003436ca","cotejado_por":"Abg. y Not. Fredy Omar Pinel Flores — CLO / Director Maya Lex — 2026-11-15","ocr_text_sha256":"7a1fc45e113b3da60efe70286446037192adfdc6856a5582c3a05753dec70d2d","norm_id":"HN:DECRETO_284_2013","instrumento_id":"DECRETO_284_2013","ingest_batch":"PILOTO_D284_2013_01","ordinal":36,"article_sha256":"75a36b3c9520b75687587ade293abc5256a5aeba6920449cbdd3500651d013b9","vigencia":"UNKNOWN","revision_pendiente":true,"marcas":[]}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','ley',NULL,true,'DECRETO_284_2013','36','6c65142de65447731e3406bf619d314f2e29f874b0d5c0878cff125e9d76a368','PILOTO_D284_2013_01',now()),
('PILOTO_D284_2013_01:DECRETO_284_2013:37','mayalex_normativos','10_LEYES_REGLAMENTOS','- Derogar los Artículos 380, 381, 382 y
